std::string CloudSignIn::link_url(const std::string& link) const
{
    // JusPrin's own Terms and Privacy Policy: JusPrin accounts are separate
    // from Obico's. The pages have no site menu leading on to Obico's.
    if (link == "terms")
        return "https://www.obico.io/jusprin-terms.html";
    if (link == "privacy")
        return "https://www.obico.io/jusprin-privacy.html";
    if (link == "reset_password")
        return m_server + "/accounts/password/reset/";
    return {};
}

std::optional<CloudAccountRecord> CloudSignIn::account() const
{
    if (!m_store.load)
        return std::nullopt;
    std::optional<CloudAccountRecord> record = m_store.load();
    if (!record || record->token.empty())
        return std::nullopt;
    return record;
}

bool CloudSignIn::sign_out()
{
    const std::optional<CloudAccountRecord> record = account();
    if (!record || !m_store.erase || !m_store.erase())
        return false;
    cancel();
    if (m_deps.revoke)
        m_deps.revoke(m_server + "/o/revoke_token/", kCloudClientId, record->token);
    return true;
}

