{
    if (progress.status != OnboardingStatus::Unfinished)
        return OnboardingStep::Hidden;
    // The welcome shows once whatever is already set up: a key, or a file
    // opened at launch.
    if (!progress.welcome_left)
        return OnboardingStep::Welcome;
